INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'monument', 'n.', '/ˈmɒnjumənt/', '纪念碑;遗迹;不朽的作品', 'Stonehenge is an ancient monument that still puzzles experts.', '巨石阵是一处至今仍让专家困惑的古老遗迹。', 'Exploring the Unknown', 1, 0, 'senior', 'wordlist', 'elective3', 'U3', 'an ancient monument', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'mystery', 'n.', '/ˈmɪstri/', '谜;神秘的事物;神秘', 'How the stones were moved remains a mystery to this day.', '这些石头是如何被搬运的至今仍是个谜。', 'Exploring the Unknown', 2, 0, 'senior', 'wordlist', 'elective3', 'U3', 'solve a mystery', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'theory', 'n.', '/ˈθɪəri/', '理论;学说;看法', 'One theory says that Stonehenge was used as a calendar.', '一种理论认为巨石阵曾被用作日历。', 'Exploring the Unknown', 3, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a popular theory', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'evidence', 'n.', '/ˈevɪdəns/', '证据;迹象', 'There is no solid evidence that aliens built the monument.', '没有确凿证据表明这处遗迹是外星人建造的。', 'Exploring the Unknown', 4, 0, 'senior', 'wordlist', 'elective3', 'U3', 'solid evidence', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'belief', 'n.', '/bɪˈliːf/', '信念;看法;相信', 'Columbus held a firm belief that the world was round.', '哥伦布坚信世界是圆的。', 'Exploring the Unknown', 5, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a firm belief', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'doubt', 'n.', '/daʊt/', '怀疑;疑问', 'There is no doubt that the trench is the deepest place on Earth.', '毫无疑问,这条海沟是地球上最深的地方。', 'Exploring the Unknown', 6, 0, 'senior', 'wordlist', 'elective3', 'U3', 'no doubt', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'construction', 'n.', '/kənˈstrʌkʃn/', '建造;建筑;结构', 'The construction of Stonehenge took place over many centuries.', '巨石阵的建造历经了许多个世纪。', 'Exploring the Unknown', 7, 0, 'senior', 'wordlist', 'elective3', 'U3', 'the construction of Stonehenge', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'primitive', 'adj.', '/ˈprɪmətɪv/', '原始的;远古的;简单的', 'Some experts call Stonehenge a kind of primitive computer.', '一些专家把巨石阵称作一种原始的计算机。', 'Exploring the Unknown', 8, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a primitive computer', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'predict', 'v.', '/prɪˈdɪkt/', '预言;预报;预测', 'He claimed that the stones could predict an eclipse.', '他声称这些石头能预测日食。', 'Exploring the Unknown', 9, 0, 'senior', 'wordlist', 'elective3', 'U3', 'predict an eclipse', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'eclipse', 'n.', '/ɪˈklɪps/', '日食;月食', 'Ancient people were amazed by a sudden eclipse of the sun.', '突如其来的日食令古人惊叹不已。', 'Exploring the Unknown', 10, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a solar eclipse', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'solstice', 'n.', '/ˈsɒlstɪs/', '至(点);(夏或冬)至', 'The stones point to the sun at the summer solstice.', '这些石头在夏至时指向太阳。', 'Exploring the Unknown', 11, 0, 'senior', 'wordlist', 'elective3', 'U3', 'the summer solstice', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'uncertainty', 'n.', '/ʌnˈsɜːtnti/', '无把握;不确定的事;疑团', 'There is still great uncertainty about who built the monument.', '关于这处遗迹的建造者仍有很大的不确定性。', 'Exploring the Unknown', 12, 0, 'senior', 'wordlist', 'elective3', 'U3', 'great uncertainty', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'calculate', 'v.', '/ˈkælkjuleɪt/', '计算;推算;预测', 'How could they calculate the movements of the sun and the moon?', '他们怎么能推算出太阳和月亮的运行呢?', 'Exploring the Unknown', 13, 0, 'senior', 'wordlist', 'elective3', 'U3', 'calculate the movements', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'unknown', 'adj.', '/ˌʌnˈnəʊn/', '未知的;不详的', 'Humans have always longed to explore the unknown.', '人类一直渴望探索未知。', 'Exploring the Unknown', 14, 0, 'senior', 'wordlist', 'elective3', 'U3', 'explore the unknown', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'desire', 'n.', '/dɪˈzaɪə(r)/', '愿望;欲望;渴望', 'People have a strong desire to go beyond familiar places.', '人们有一种走出熟悉之地的强烈渴望。', 'Exploring the Unknown', 15, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a strong desire', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'beyond', 'prep./adv.', '/bɪˈjɒnd/', '在……另一边;超出;在更远处', 'Early explorers wanted to see what lay beyond the ocean.', '早期的探险者想看看海洋那一边有什么。', 'Exploring the Unknown', 16, 0, 'senior', 'wordlist', 'elective3', 'U3', 'go beyond', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'universe', 'n.', '/ˈjuːnɪvɜːs/', '宇宙;天地万物', 'One day humans may explore the vastness of the universe.', '总有一天人类或许会探索浩瀚的宇宙。', 'Exploring the Unknown', 17, 0, 'senior', 'wordlist', 'elective3', 'U3', 'the whole universe', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'humanity', 'n.', '/hjuːˈmænəti/', '(统称)人类;人性', 'There seems to be no end to humanity''s appetite for exploring.', '人类探索的渴望似乎没有尽头。', 'Exploring the Unknown', 18, 0, 'senior', 'wordlist', 'elective3', 'U3', 'humanity''s appetite', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'surroundings', 'n.', '/səˈraʊndɪŋz/', '周围的事物;环境', 'We are born wanting to explore our surroundings.', '我们生来就想探索周遭的环境。', 'Exploring the Unknown', 19, 0, 'senior', 'wordlist', 'elective3', 'U3', 'explore our surroundings', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'isolated', 'adj.', '/ˈaɪsəleɪtɪd/', '孤立的;偏远的;隔绝的', 'Vale do Javari is one of the most isolated places on Earth.', '查瓦利河谷是地球上最与世隔绝的地方之一。', 'Exploring the Unknown', 20, 0, 'senior', 'wordlist', 'elective3', 'U3', 'an isolated place', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'trench', 'n.', '/trentʃ/', '海沟;沟;渠', 'Few people have ever reached the bottom of the deep trench.', '很少有人曾到达过这条深沟的底部。', 'Exploring the Unknown', 21, 0, 'senior', 'wordlist', 'elective3', 'U3', 'the deep trench', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'previous', 'adj.', '/ˈpriːviəs/', '先前的;以往的', 'Previous expeditions revealed strange creatures in the deep sea.', '以往的探险曾发现深海中的奇怪生物。', 'Exploring the Unknown', 22, 0, 'senior', 'wordlist', 'elective3', 'U3', 'previous expeditions', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'indigenous', 'adj.', '/ɪnˈdɪdʒənəs/', '本地的;土生土长的', 'The rainforest is home to many indigenous people.', '这片雨林是许多原住民的家园。', 'Exploring the Unknown', 23, 0, 'senior', 'wordlist', 'elective3', 'U3', 'indigenous people', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'territory', 'n.', '/ˈterətri/', '领地;版图;领土', 'The valley is one of the largest indigenous territories in Brazil.', '这片河谷是巴西最大的原住民领地之一。', 'Exploring the Unknown', 24, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a vast territory', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'system', 'n.', '/ˈsɪstəm/', '系统;体系;制度', 'The Javari is the most important river system in the region.', '查瓦利河是该地区最重要的河流水系。', 'Exploring the Unknown', 25, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a river system', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'tribe', 'n.', '/traɪb/', '部落', 'Some tribes were first discovered through satellite images.', '一些部落最初是通过卫星图像被发现的。', 'Exploring the Unknown', 26, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a hidden tribe', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'satellite', 'n.', '/ˈsætəlaɪt/', '人造卫星;卫星', 'Satellite images helped scientists find the hidden village.', '卫星图像帮助科学家找到了那个隐蔽的村落。', 'Exploring the Unknown', 27, 0, 'senior', 'wordlist', 'elective3', 'U3', 'satellite images', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'prohibit', 'v.', '/prəˈhɪbɪt/', '(尤指以法令)禁止', 'Brazilian law prohibits outsiders from entering the region.', '巴西法律禁止外来者进入该地区。', 'Exploring the Unknown', 28, 0, 'senior', 'wordlist', 'elective3', 'U3', 'prohibit entry', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'dedicate', 'v.', '/ˈdedɪkeɪt/', '把……奉献给;致力于', 'A local group is dedicated to protecting the forest.', '一个当地组织致力于保护这片森林。', 'Exploring the Unknown', 29, 0, 'senior', 'wordlist', 'elective3', 'U3', 'dedicate oneself to', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'exploitation', 'n.', '/ˌeksplɔɪˈteɪʃn/', '开发;开采;剥削', 'The reserve protects the forest from exploitation.', '这片保护区使森林免遭开发。', 'Exploring the Unknown', 30, 0, 'senior', 'wordlist', 'elective3', 'U3', 'protect from exploitation', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'reserve', 'n.', '/rɪˈzɜːv/', '保护区;储备', 'Sharp limestone makes this nature reserve dangerous to explore.', '锋利的石灰岩使这处自然保护区探索起来很危险。', 'Exploring the Unknown', 31, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a nature reserve', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'needle', 'n.', '/ˈniːdl/', '针;针状物', 'The needle-shaped rocks rise sharply from the ground.', '这些针状的岩石从地面尖锐地耸起。', 'Exploring the Unknown', 32, 0, 'senior', 'wordlist', 'elective3', 'U3', 'needle-shaped rocks', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'limestone', 'n.', '/ˈlaɪmstəʊn/', '石灰岩', 'The limestone formations are terribly sharp and dangerous.', '这些石灰岩岩柱锋利无比、十分危险。', 'Exploring the Unknown', 33, 0, 'senior', 'wordlist', 'elective3', 'U3', 'limestone formations', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'pose', 'v.', '/pəʊz/', '造成(威胁、问题等);引起', 'The sharp rocks pose a serious danger to explorers.', '这些锋利的岩石给探险者带来严重危险。', 'Exploring the Unknown', 34, 0, 'senior', 'wordlist', 'elective3', 'U3', 'pose a danger', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'derive', 'v.', '/dɪˈraɪv/', '起源于;从……得到', 'The name derives from a local word about walking.', '这个名字源自一个与行走有关的当地词语。', 'Exploring the Unknown', 35, 0, 'senior', 'wordlist', 'elective3', 'U3', 'derive from a word', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'barefoot', 'adv./adj.', '/ˈbeəfʊt/', '赤着脚(地)', 'No one can safely walk barefoot across these rocks.', '没人能赤脚安全地走过这些岩石。', 'Exploring the Unknown', 36, 0, 'senior', 'wordlist', 'elective3', 'U3', 'walk barefoot', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'sharp', 'adj.', '/ʃɑːp/', '锋利的;尖的;急剧的', 'The stones have edges sharp enough to cut through flesh.', '这些石头的边缘锋利得足以划破皮肉。', 'Exploring the Unknown', 37, 0, 'senior', 'wordlist', 'elective3', 'U3', 'a sharp edge', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'flesh', 'n.', '/fleʃ/', '(动物或人的)肉;肌肉', 'A fall here could cut the flesh with deadly effect.', '在这里摔倒可能会划破皮肉,造成致命后果。', 'Exploring the Unknown', 38, 0, 'senior', 'wordlist', 'elective3', 'U3', 'cut the flesh', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'enormous', 'adj.', '/ɪˈnɔːməs/', '巨大的;庞大的', 'Each enormous stone weighs as much as fifty tons.', '每块巨大的石头重达五十吨。', 'Exploring the Unknown', 39, 0, 'senior', 'wordlist', 'elective3', 'U3', 'an enormous stone', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'incredible', 'adj.', '/ɪnˈkredəbl/', '难以置信的;惊人的', 'Moving the stones must have been an incredible journey.', '搬运这些石头一定是一次惊人的旅程。', 'Exploring the Unknown', 40, 0, 'senior', 'wordlist', 'elective3', 'U3', 'an incredible journey', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'origin', 'n.', '/ˈɒrɪdʒɪn/', '起源;由来;出身', 'The origin of this historic site is still unknown to us.', '这处历史遗址的由来我们至今仍不清楚。', 'Exploring the Unknown', 41, 0, 'senior', 'wordlist', 'elective3', 'U3', 'the origin of the site', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'refer to', 'phr.', '/rɪˈfɜː tə/', '提到;涉及;指的是', 'The guide often referred to an old theory about the giants.', '导游常常提到一个关于巨人的古老理论。', 'Exploring the Unknown', 42, 0, 'senior', 'wordlist', 'elective3', 'U3', 'refer to a theory', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'devote ... to', 'phr.', '/dɪˈvəʊt tə/', '把……献给;致力于', 'Why did ancient people devote so much energy to this monument?', '古人为何把这么多精力投入到这处遗迹上?', 'Exploring the Unknown', 43, 0, 'senior', 'wordlist', 'elective3', 'U3', 'devote time to', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'take place', 'phr.', '/teɪk ˈpleɪs/', '(按计划)发生;进行', 'The rebuilding took place over hundreds of years.', '这次重建历经数百年才完成。', 'Exploring the Unknown', 44, 0, 'senior', 'wordlist', 'elective3', 'U3', 'take place over years', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'in spite of', 'phr.', '/ɪn ˈspaɪt əv/', '不管;尽管', 'In spite of the danger, explorers still long to reach the place.', '尽管危险,探险者仍渴望抵达那个地方。', 'Exploring the Unknown', 45, 0, 'senior', 'wordlist', 'elective3', 'U3', 'in spite of the danger', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'in fact', 'phr.', '/ɪn ˈfækt/', '确切地说;事实上', 'In fact, the word means "a place where one cannot walk."', '确切地说,这个词意为“一个无法行走的地方”。', 'Exploring the Unknown', 46, 0, 'senior', 'wordlist', 'elective3', 'U3', 'in fact', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'derive from', 'phr.', '/dɪˈraɪv frəm/', '源自;起源于', 'The strange name is derived from a local word.', '这个奇怪的名字源自一个当地词语。', 'Exploring the Unknown', 47, 0, 'senior', 'wordlist', 'elective3', 'U3', 'derive from a local word', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'in the form of', 'phr.', '/ɪn ðə ˈfɔːm əv/', '以……的形式', 'Water may have arrived in the form of ice on an asteroid.', '水或许是以冰的形式随小行星到来的。', 'Exploring the Unknown', 48, 0, 'senior', 'wordlist', 'elective3', 'U3', 'in the form of ice', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'be involved in', 'phr.', '/bi ɪnˈvɒlvd ɪn/', '参与;牵涉到', 'No one knows how many people were involved in the work.', '没人知道有多少人参与了这项工作。', 'Exploring the Unknown', 49, 0, 'senior', 'wordlist', 'elective3', 'U3', 'be involved in the work', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'for some reason', 'phr.', '/fə səm ˈriːzn/', '出于某种原因', 'For some reason, the early people rearranged the bluestones.', '出于某种原因,远古的人们重新排列了这些蓝砂岩。', 'Exploring the Unknown', 50, 0, 'senior', 'wordlist', 'elective3', 'U3', 'for some reason', NULL, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se3u3.01', '①抽象名词 + that 同位语从句(从句完整,that 只连接、不作成分)', 'A2', 12, '上外版选择性必修第三册 U3 — belief/fact/idea/news/evidence/theory/hope/truth 等抽象名词后,接一个本身完整的句子来说明其内容,用 that 连接;that 在从句里不缺主语、宾语或状语,只起连接作用,不可用 which/what/where 等替换。', 1, 'elective3', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se3u3.02', '②同位语从句 vs 定语从句(完整→that;缺主/宾→which/who;缺地点/时间→where/when)', 'A2', 12, '上外版选择性必修第三册 U3 — 同一个抽象名词后,若后面的句子完整、只是补充说明其内容,用 that(同位语);若句子缺主语或宾语,则是定语从句,指物用 which、指人用 who;若只缺地点/时间状语,用 where/when。靠''从句缺不缺成分''来判断。', 2, 'elective3', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se3u3.03', '③whether / what / how / why / when 引导的同位语从句', 'A2', 12, '上外版选择性必修第三册 U3 — question/problem 等表疑问的名词后,若内容是''是否'',用 whether(不用 that);若从句缺名词性成分用 what;若只缺方式/原因/时间状语,用 how/why/when。靠从句''缺什么成分、表什么意思''唯一确定。', 3, 'elective3', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.01'), 'Columbus had a firm belief ____ the world was round.', 'that', 'which', 'what', 'where', 'A', 'belief 后的句子 ''the world was round'' 本身完整、不缺任何成分,只补充说明这一信念的内容,用 that 连接;其余词都要求从句里缺一个成分,这里不缺。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.01'), 'There is strong evidence ____ Stonehenge was once used as a calendar.', 'which', 'that', 'where', 'what', 'B', 'evidence 后的从句完整,只说明''证据的内容'',用 that;which/what 需从句缺成分,where 需缺地点状语,都不符合。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.01'), 'Scientists put forward the idea ____ Earth''s water was delivered by an asteroid.', 'what', 'which', 'that', 'when', 'C', 'idea 后的句子完整,是对这一观点内容的说明,用 that;其余词在完整从句里没有可承担的成分。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.01'), 'The news ____ the Chang''e-4 probe had landed thrilled the whole country.', 'which', 'what', 'whose', 'that', 'D', 'news 后从句完整,说明消息的内容,用 that;which/what/whose 都要求从句缺成分。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.01'), 'Many people accept the theory ____ the giant statues were carved by hand.', 'that', 'which', 'what', 'where', 'A', 'theory 后的从句完整,补充理论的具体内容,用 that。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.01'), 'Archaeologists made the discovery ____ the bluestones came from South Wales.', 'what', 'that', 'which', 'where', 'B', 'discovery 后从句完整,说明发现的内容,用 that;此处不缺主宾,也不缺地点状语。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.01'), 'The fact ____ no one knows how the trilithons were raised still amazes visitors.', 'which', 'what', 'that', 'who', 'C', 'fact 后从句完整,是对''事实''内容的说明,用 that。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.01'), 'We cannot ignore the truth ____ many ancient sites remain unexplained.', 'which', 'where', 'what', 'that', 'D', 'truth 后从句完整,说明真相的内容,用 that。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.01'), 'There is a belief ____ aliens from another world helped build the monument.', 'that', 'what', 'which', 'whose', 'A', 'belief 后从句完整,补充说明这一信念,用 that。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.01'), 'Researchers reached the conclusion ____ the trench is the deepest place on Earth.', 'which', 'that', 'what', 'where', 'B', 'conclusion 后从句完整,说明结论的内容,用 that。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.01'), 'The suggestion ____ we should leave the ruins untouched sounds wise.', 'which', 'what', 'that', 'who', 'C', 'suggestion 后从句完整,说明建议的内容,用 that。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.01'), 'Nobody can deny the fact ____ life exists even at the bottom of the ocean.', 'what', 'which', 'where', 'that', 'D', 'fact 后从句完整,说明事实内容,用 that。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.01'), 'The old story spread the idea ____ a monster still lives in the lake.', 'that', 'which', 'what', 'when', 'A', 'idea 后从句完整,说明这一说法的内容,用 that。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.01'), 'There is little evidence ____ the islanders ever reached South America.', 'which', 'that', 'where', 'what', 'B', 'evidence 后从句完整,说明证据所指的内容,用 that。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.01'), 'The report confirmed the news ____ a new species had been found in the forest.', 'what', 'which', 'that', 'whose', 'C', 'news 后从句完整,说明消息内容,用 that。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.01'), 'She had a strong feeling ____ the cave was hiding an ancient secret.', 'which', 'what', 'where', 'that', 'D', 'feeling 后从句完整,说明这种感觉的内容,用 that。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.01'), 'The hope ____ humans will one day explore the whole universe drives science on.', 'that', 'which', 'what', 'who', 'A', 'hope 后从句完整,说明希望的内容,用 that。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.01'), 'Everyone was struck by the discovery ____ the deep trench was full of life.', 'what', 'that', 'which', 'where', 'B', 'discovery 后从句完整,说明发现的内容,用 that。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.01'), 'He made the claim ____ he had crossed the great desert entirely alone.', 'which', 'what', 'that', 'whose', 'C', 'claim 后从句完整,说明所声称的内容,用 that。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.01'), 'The belief ____ giants once ruled the island comes from old local legends.', 'which', 'what', 'where', 'that', 'D', 'belief 后从句完整,说明这一信念的内容,用 that。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.02'), 'The discovery ____ the trench supports life surprised many biologists.', 'that', 'which', 'where', 'when', 'A', 'discovery 后的句子完整(不缺主宾或状语),是对发现内容的说明,属同位语从句,用 that。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.02'), 'Experts hold the view ____ ancient people had real astronomical knowledge.', 'which', 'that', 'when', 'where', 'B', 'view 后从句完整,说明观点内容,是同位语从句,用 that。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.02'), 'There is growing evidence ____ the statues were moved by rocking them.', 'which', 'where', 'that', 'when', 'C', 'evidence 后从句完整,说明证据内容,用 that(同位语)。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.02'), 'The idea ____ the limestone can cut through flesh keeps tourists away.', 'which', 'where', 'when', 'that', 'D', 'idea 后从句完整,说明这一看法的内容,用 that。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.02'), 'No one doubts the fact ____ the rainforest hides uncontacted tribes.', 'that', 'which', 'when', 'where', 'A', 'fact 后从句完整,说明事实内容,用 that。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.02'), 'We were excited by the news ____ a probe had reached the far side of the moon.', 'which', 'that', 'where', 'when', 'B', 'news 后从句完整,说明消息内容,用 that。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.02'), 'The belief ____ the lake hides a monster still draws many visitors.', 'which', 'where', 'that', 'when', 'C', 'belief 后从句完整,说明信念内容,用 that。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.02'), 'Scientists support the theory ____ water came to Earth from outer space.', 'which', 'when', 'where', 'that', 'D', 'theory 后从句完整,说明理论内容,用 that。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.02'), 'The evidence ____ the archaeologists uncovered proved the city was real.', 'which', 'who', 'where', 'when', 'A', '从句 ''the archaeologists uncovered ____'' 缺动词 uncovered 的宾语,是定语从句,指物用 which;who 指人、where/when 是状语都不对。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.02'), 'The deep trench ____ explorers have rarely reached is full of strange life.', 'who', 'which', 'where', 'when', 'B', '从句缺 reached 的宾语,定语从句指物用 which。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.02'), 'The ancient symbols ____ they carved still puzzle researchers today.', 'who', 'when', 'which', 'where', 'C', '从句缺 carved 的宾语,定语从句指物用 which。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.02'), 'The mysterious island ____ sailors named on Easter Day lies far out at sea.', 'who', 'where', 'when', 'which', 'D', '从句缺 named 的宾语,定语从句指物用 which。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.02'), 'This is the remote valley ____ outsiders are not allowed to set foot.', 'where', 'which', 'that', 'when', 'A', '从句完整、只缺地点状语(set foot ____),定语从句用 where;which/that 需缺主宾,这里不缺。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.02'), 'Madagascar has a reserve ____ huge needle-shaped rocks rise from the ground.', 'which', 'where', 'that', 'when', 'B', '从句缺地点状语,定语从句用 where。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.02'), 'They reached the deep part of the ocean ____ the water pressure is deadly.', 'which', 'that', 'where', 'when', 'C', '从句完整、只缺地点状语,用 where。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.02'), 'Salisbury Plain is the place ____ the ancient builders raised the huge stones.', 'which', 'that', 'when', 'where', 'D', 'raised 已有宾语 the huge stones,从句只缺地点状语,用 where。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.02'), 'Around 2,000 BCE was the time ____ the builders rearranged the bluestones.', 'when', 'where', 'which', 'that', 'A', 'rearranged 已有宾语,从句只缺时间状语,定语从句用 when。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.02'), 'Easter Day was the day ____ European sailors first saw the island.', 'where', 'when', 'which', 'that', 'B', 'saw 已有宾语 the island,从句只缺时间状语,用 when。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.02'), 'The Bronze Age was the period ____ the largest stones were pulled to the site.', 'where', 'which', 'when', 'that', 'C', '从句完整、只缺时间状语,用 when。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.02'), '2019 was the year ____ China''s probe landed on the far side of the moon.', 'where', 'which', 'that', 'when', 'D', '从句完整、只缺时间状语,用 when。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.03'), 'Scientists are studying the question ____ there is water on the moon.', 'whether', 'that', 'what', 'which', 'A', 'question 后的从句完整、内容是''是否有水'',表疑问的同位语从句用 whether;that 不能引导表疑问的同位语从句,what/which 在完整从句里无成分可担。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.03'), 'There remains the question ____ Stonehenge was really used as a cemetery.', 'that', 'whether', 'which', 'who', 'B', 'question 后内容是''是否'',用 whether;that 不可引导表疑问的同位语从句。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.03'), 'Experts discussed the question ____ aliens could ever have visited Earth.', 'that', 'what', 'whether', 'which', 'C', 'question 后表''是否''的疑问,用 whether。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.03'), 'The question ____ the old photographs are real has never been settled.', 'that', 'which', 'who', 'whether', 'D', 'question 后内容是''是否真实'',用 whether。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.03'), 'Historians argue over the question ____ the Trojan War actually happened.', 'whether', 'that', 'what', 'which', 'A', 'question 后表''是否发生过'',用 whether。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.03'), 'There is still the problem ____ such isolated tribes should be contacted.', 'that', 'whether', 'which', 'who', 'B', 'problem 后内容是''是否应该'',表疑问的同位语从句用 whether。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.03'), 'I often wonder about the question ____ the universe will ever be fully known.', 'that', 'what', 'whether', 'which', 'C', 'question 后表''是否'',用 whether。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.03'), 'There is the question ____ these strange symbols actually mean.', 'whether', 'how', 'that', 'what', 'D', '从句缺 mean 的宾语(……意味着什么),用 what;whether/how/that 都会使 mean 缺宾语而不通。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.03'), 'There is the question ____ the ancient builders were trying to record.', 'what', 'whether', 'why', 'that', 'A', '从句缺 record 的宾语,用 what。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.03'), 'The mystery ____ lies at the bottom of the trench fascinates scientists.', 'whether', 'what', 'who', 'that', 'B', '从句缺主语(……躺在海沟底部),用 what;who 指人不合,whether/that 无法充当主语。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.03'), 'The question ____ the giant statues were meant to show puzzles everyone.', 'whether', 'how', 'what', 'that', 'C', '从句缺 show 的宾语,用 what。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.03'), 'Researchers raised the question ____ the islanders ate during the hard times.', 'whether', 'why', 'that', 'what', 'D', '从句缺 ate 的宾语,用 what。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.03'), 'The question ____ the ancient people raised the trilithons remains unanswered.', 'how', 'what', 'which', 'that', 'A', 'raised 已有宾语 the trilithons,从句只缺方式状语(怎样竖起),用 how;what/which/that 无名词性空缺可担。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.03'), 'Nobody could explain the question ____ the heavy bluestones were transported.', 'what', 'how', 'which', 'that', 'B', '从句被动完整、只缺方式状语,用 how。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.03'), 'There is the question ____ early sailors found such a tiny island in the sea.', 'what', 'which', 'how', 'that', 'C', 'found 已有宾语 such a tiny island,从句只缺方式状语,用 how。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.03'), 'The question ____ the builders devoted so much energy to the site puzzles us.', 'what', 'which', 'that', 'why', 'D', '从句完整、只缺原因状语(为何投入这么多精力),用 why。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.03'), 'There remains the question ____ the islanders abandoned their stone giants.', 'why', 'what', 'who', 'that', 'A', 'abandoned 已有宾语,从句只缺原因状语,用 why。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.03'), 'No one has answered the question ____ ancient people built the huge monument.', 'what', 'why', 'which', 'that', 'B', 'built 已有宾语 the huge monument,从句只缺原因状语,用 why。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.03'), 'The question ____ the first humans reached the island is hard to answer.', 'what', 'which', 'when', 'that', 'C', 'reached 已有宾语 the island,从句只缺时间状语,用 when。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U3' AND code='se3u3.03'), 'Historians study the question ____ the second phase of building began.', 'what', 'which', 'that', 'when', 'D', '从句完整、只缺时间状语(何时开始),用 when。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Mystery of Stonehenge', 'Stonehenge, a ring of huge stones on Salisbury Plain in England, is one of the most famous ancient monuments in the world. It was put up in several stages over many centuries, beginning around 3,000 BCE, long before the wheel was invented. Some of the stones weigh as much as fifty tons, yet they were pulled to the site from areas far away. How the early people managed to move and raise such enormous stones is still a puzzle that no one can fully explain. Even more mysterious is the reason behind the whole project. Some historians once thought the place was a burial ground, since human bones have been found nearby. Today, however, many experts believe it acted as a kind of calendar, because certain stones point to the sun at the summer and winter solstices. A few people even hold the wild belief that visitors from space lent a hand. After thousands of years, Stonehenge still keeps its secrets.', '说明·巨石阵之谜', 161, '[{"q":"When did the building of Stonehenge begin?","answer":"A","options":["Around five thousand years ago, before the wheel existed.","Only a few hundred years ago.","Soon after cars were invented.","During modern times."],"explanation":"原文说始于约公元前3000年、远早于车轮发明,即约五千年前。"},{"q":"What still puzzles people about the stones?","answer":"B","options":["Who first found the human bones.","How such heavy stones were moved and lifted.","Why the wheel was invented so late.","Where the sun rises each day."],"explanation":"原文说人们无法解释早期的人如何搬运、竖起这些巨石。"},{"q":"What do many experts believe today about Stonehenge?","answer":"A","options":["It was probably used to mark the seasons, like a calendar.","It was a space station built for aliens.","It was a factory for making computers.","It was a place for growing crops."],"explanation":"原文说今天许多专家认为它像一种日历,石头在夏至冬至指向太阳。"}]'::jsonb, '[{"word":"monument","cn":"遗迹;纪念碑"},{"word":"solstice","cn":"至(点)"},{"word":"belief","cn":"信念"}]'::jsonb, 2, 'elective3', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Into the Deepest Trench', 'Far down in the western Pacific Ocean lies the Mariana Trench, the deepest place in all the world''s oceans. At one narrow point, known as the Challenger Deep, it drops to more than ten thousand metres below the surface — deep enough to swallow the highest mountain on land. Because of this extreme depth, the trench is one of the least explored regions on the planet. The water pressure down there is so powerful that it would crush most equipment in seconds, and almost no sunlight ever reaches the bottom. For a long time people doubted that anything could survive in such a place. Yet earlier voyages have proved them wrong. Cameras and small submarines have brought back images of strange fish and other creatures that somehow make the cold, dark deep their home. Each new trip raises fresh questions about how life manages to exist where conditions seem impossible, and scientists are keen to go back and learn more.', '说明·马里亚纳海沟', 160, '[{"q":"Why is the Mariana Trench so little explored?","answer":"B","options":["It is always crowded with tourists.","Its great depth and crushing pressure make it hard to reach.","It is hidden under a thick forest.","It lies too close to the sun."],"explanation":"原文说因极深、水压强大会瞬间压坏设备,所以难以到达探索。"},{"q":"What did earlier voyages reveal?","answer":"C","options":["Nothing at all can be found down there.","The water there is warm and bright.","Some creatures actually live in the deep, dark water.","The trench is shallower than people thought."],"explanation":"原文说相机和潜水器带回了深海生物的影像,证明那里有生命。"},{"q":"How do scientists feel about the trench now?","answer":"D","options":["They have lost all interest in it.","They believe it is already fully understood.","They hope it will be closed forever.","They want to go back and keep studying it."],"explanation":"原文末句说科学家渴望再去、了解更多。"}]'::jsonb, '[{"word":"trench","cn":"海沟"},{"word":"previous","cn":"先前的"},{"word":"pose","cn":"造成(危险)"}]'::jsonb, 2, 'elective3', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'A Hidden World in Brazil', 'Deep in the rainforests of Brazil lies Vale do Javari, one of the largest areas of protected land set aside for native peoples. Hidden among its thick trees and winding rivers live a number of tribes who have had almost no contact with the outside world. In fact, several of these groups were first noticed only through pictures taken by satellites high above the forest. The region is extremely difficult to reach. Endless trees, wide rivers and the absence of roads keep most travellers far away, and that is exactly the point. Brazilian law forbids outsiders from going in, and a local organisation works hard to guard the area and keep its rich plant and animal life safe. Some people argue that these communities should be visited and studied, while others insist that the kindest choice is to leave them completely alone. For now, Vale do Javari remains a green world that very few people will ever see with their own eyes.', '说明·查瓦利河谷', 162, '[{"q":"How were some of the tribes first noticed?","answer":"A","options":["By studying images taken from space.","By driving along the main roads.","By reading very old maps.","By chatting with city visitors."],"explanation":"原文说有些部落最初是通过卫星拍摄的图像被发现的。"},{"q":"Why is the region so hard to reach?","answer":"B","options":["It is surrounded by tall mountains of ice.","Dense trees, broad rivers and a lack of roads block the way.","It is buried under desert sand.","It is far too crowded with tourists."],"explanation":"原文说茂密树木、宽阔河流和没有道路把旅行者挡在外面。"},{"q":"What do some people think should be done with the tribes?","answer":"C","options":["Everyone agrees they must be moved to cities.","All visitors should quickly build roads to them.","Some believe it is best not to disturb the people there.","The forest around them should be cut down."],"explanation":"原文说一些人坚持最善意的选择是完全不去打扰他们。"}]'::jsonb, '[{"word":"indigenous","cn":"本地的;土生土长的"},{"word":"tribe","cn":"部落"},{"word":"satellite","cn":"卫星"}]'::jsonb, 2, 'elective3', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Forest of Stone Needles', 'On the western side of Madagascar stands one of the strangest landscapes on Earth: the Tsingy de Bemaraha. Here, tall grey rocks rise from the ground like a forest of stone needles, their edges so sharp that they can cut through skin. The name itself comes from a local word meaning a place where a person cannot walk barefoot, and anyone who has seen these rocks understands why. Reaching the area is hard, and moving through it is harder still, since one careless step among the blades of limestone can cause a serious injury. In spite of these dangers, the place has been protected since 1990 as a World Heritage Site. Its towers of rock shelter all kinds of wildlife, and scientists have even found animals here that live nowhere else. Visitors are let in only in small numbers, reaching the reserve by road or by light plane. For the brave few who go, it offers a view of nature that they will never forget.', '说明·磬吉石林', 165, '[{"q":"What does the local name of the place mean?","answer":"D","options":["A land of soft green grass.","A warm and friendly beach.","A busy city full of people.","Somewhere a person cannot walk without shoes."],"explanation":"原文说这个名字源自当地词语,意为''人不能赤脚行走的地方''。"},{"q":"Why is the place so dangerous?","answer":"A","options":["Its very sharp rocks can badly hurt anyone who slips.","Wild storms strike it every hour.","The ground is always covered in thick ice.","Poisonous smoke fills the whole air."],"explanation":"原文说尖利的石灰岩刀刃一不小心就会造成严重伤害。"},{"q":"Why is the place valuable to scientists?","answer":"B","options":["It produces large amounts of oil.","Certain animals there are found in no other place on Earth.","It is the easiest reserve in the world to visit.","It has the warmest weather in all of Africa."],"explanation":"原文说科学家在这里发现了别处没有的动物。"}]'::jsonb, '[{"word":"limestone","cn":"石灰岩"},{"word":"barefoot","cn":"赤脚地"},{"word":"reserve","cn":"保护区"}]'::jsonb, 2, 'elective3', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Giants of Easter Island', 'In the middle of the vast Pacific Ocean lies a tiny piece of land called Easter Island, famous for its rows of giant stone figures. European sailors gave the island its name when they arrived there on Easter Day, long ago. What they found amazed them: hundreds of huge statues, some weighing many tons and standing several metres tall, staring silently out across the land. For years people have asked the same questions. Who carved these giants, and what were they meant to stand for? And, perhaps most puzzling of all, how did a small group of islanders, working only with simple tools, move such heavy figures across rough ground? Many ideas have been suggested, from clever wooden sledges to teams of people gently rocking the statues forward step by step. None of these explanations has been fully proved. The stone faces of Easter Island still gaze out to sea, guarding the secret of how they came to be.', '说明·复活节岛石像', 159, '[{"q":"How did the island get its name?","answer":"C","options":["It was shaped exactly like an egg.","The local people chose the name themselves.","Visiting sailors reached it on the day of Easter.","A king named it after his daughter."],"explanation":"原文说欧洲水手在复活节那天到达,因而给岛取了这个名字。"},{"q":"What puzzles people most about the statues?","answer":"D","options":["Why the island is so cold all year.","When the first cars arrived there.","Who built the island''s airport.","How such heavy statues were moved using only basic tools."],"explanation":"原文说最令人困惑的是岛民如何仅用简单工具搬动如此沉重的石像。"},{"q":"What has happened to the many explanations?","answer":"A","options":["So far, not one of them has been clearly confirmed.","All of them have been proved true.","They were never written down anywhere.","Everyone now agrees on a single answer."],"explanation":"原文说这些说法没有一个被完全证实。"}]'::jsonb, '[{"word":"incredible","cn":"难以置信的"},{"word":"previous","cn":"先前的"},{"word":"origin","cn":"起源"}]'::jsonb, 2, 'elective3', 'U3', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Legend of Loch Ness', 'For hundreds of years, stories have spread about a strange creature said to live in the deep, cold waters of Loch Ness in Scotland. People call it ''Nessie'', and many claim to have seen it rise for a moment before slipping back beneath the surface. Over time, thousands of sightings have been written down, and a few blurry photographs have appeared as well. Yet, in spite of all the excitement, no firm proof has ever been found to show that such an animal really exists. Some believers suggest that Nessie could be a kind of ancient sea reptile that somehow survived to the present day. Scientists, however, point out that a creature of that size would need to come up for air often, and would surely have been filmed clearly by now. Searches using modern underwater equipment have turned up nothing unusual. Still, the legend refuses to die, and every year curious visitors travel to the lake, hoping to catch sight of the monster for themselves.', '说明·尼斯湖水怪', 166, '[{"q":"What is ''Nessie'' said to be?","answer":"B","options":["A famous singer from Scotland.","A mysterious animal believed to live in a Scottish lake.","An old wooden sailing ship.","A rare kind of mountain bird."],"explanation":"原文说传说中有一种奇怪生物住在苏格兰尼斯湖的深水里。"},{"q":"What is the problem with the sightings and photographs?","answer":"C","options":["They were all taken just last week.","They clearly show a large reptile.","They still fail to prove the creature truly exists.","They were carefully drawn by scientists."],"explanation":"原文说尽管热闹,却从未找到确凿证据证明这种动物真的存在。"},{"q":"Why do scientists doubt the story?","answer":"D","options":["Scotland has no lakes at all.","Nobody has ever once visited the lake.","The water there is far too warm for any life.","An animal that big would surely have been recorded clearly already."],"explanation":"原文说那么大的动物得经常浮上来呼吸,早该被清楚拍到了。"}]'::jsonb, '[{"word":"evidence","cn":"证据"},{"word":"doubt","cn":"怀疑"},{"word":"previous","cn":"先前的"}]'::jsonb, 2, 'elective3', 'U3', 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U3', 'The Bermuda Triangle', 'The Bermuda Triangle is an area of the Atlantic Ocean that has long been a (1)____ to people around the world. Since 1945, more than a hundred ships and planes are said to have (2)____ there, often without leaving a single (3)____ behind. Many strange (4)____ have been put forward to explain these losses, but few people are truly (5)____ by them. Some writers blamed sudden storms; others (6)____ to magnetic forces or even aliens. Careful scientists, however, (7)____ that the area is no more dangerous than many other busy parts of the sea. They point out that heavy traffic and bad weather can easily (8)____ accidents. In (9)____, records show that ships go missing here no more often than (10)____. Even so, the puzzle of the Triangle still excites the imagination of millions.', 134, 2, '[{"q":"1","answer":"A","options":["mystery","holiday","machine","garden"],"explanation":"a mystery to people 对人们而言是个谜。"},{"q":"2","answer":"B","options":["returned","disappeared","improved","agreed"],"explanation":"have disappeared there 在那里消失,与''没留下痕迹''呼应。"},{"q":"3","answer":"C","options":["price","song","clue","ticket"],"explanation":"without leaving a single clue 没留下一丝线索。"},{"q":"4","answer":"D","options":["gardens","machines","tickets","theories"],"explanation":"strange theories 奇怪的理论(被提出来解释)。"},{"q":"5","answer":"A","options":["convinced","painted","cooked","opened"],"explanation":"convinced by them 被它们说服。"},{"q":"6","answer":"B","options":["sold","pointed","cooked","slept"],"explanation":"pointed to magnetic forces 把原因指向磁力。"},{"q":"7","answer":"C","options":["sell","sleep","insist","cook"],"explanation":"scientists insist that 科学家坚持认为。"},{"q":"8","answer":"D","options":["sell","paint","sing","cause"],"explanation":"cause accidents 引发事故。"},{"q":"9","answer":"A","options":["fact","water","music","grass"],"explanation":"in fact 事实上。"},{"q":"10","answer":"B","options":["abroad","elsewhere","upstairs","yesterday"],"explanation":"no more often than elsewhere 不比别处更频繁。"}]'::jsonb, 1, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U3', 'China''s Journey to the Far Side of the Moon', 'In early 2019, China made history when its Chang''e-4 probe became the first to land softly on the far (1)____ of the moon. This part of the moon can never be seen from Earth, so the (2)____ was extremely difficult. Because no radio signal can travel (3)____ from there to our planet, engineers first sent up a special satellite to (4)____ messages between the probe and the control centre. After a long journey, the probe (5)____ touched down and began to explore. It took clear (6)____ of the strange grey surface and studied the soil with care. Scientists hope these samples will help them (7)____ how the moon was formed long ago. The (8)____ was praised around the world as a great step forward. It also showed that the desire to (9)____ the unknown is as strong as ever. One day, such work may even help humans build a research (10)____ on the moon.', 154, 2, '[{"q":"1","answer":"C","options":["price","song","side","garden"],"explanation":"the far side of the moon 月球的远端。"},{"q":"2","answer":"D","options":["holiday","market","dinner","landing"],"explanation":"the landing was difficult 着陆很困难。"},{"q":"3","answer":"A","options":["directly","loudly","sweetly","politely"],"explanation":"travel directly 直接传送(信号)。"},{"q":"4","answer":"B","options":["sell","carry","cook","paint"],"explanation":"carry messages between 在两者间传递信息。"},{"q":"5","answer":"C","options":["never","hardly","finally","rarely"],"explanation":"finally touched down 终于着陆,后文确实落了地。"},{"q":"6","answer":"D","options":["prices","songs","tickets","pictures"],"explanation":"took clear pictures 拍下清晰的照片。"},{"q":"7","answer":"A","options":["understand","sell","lose","waste"],"explanation":"help them understand 帮助他们理解。"},{"q":"8","answer":"B","options":["garden","mission","market","dinner"],"explanation":"the mission was praised 这次任务受到称赞。"},{"q":"9","answer":"C","options":["sell","cook","explore","paint"],"explanation":"explore the unknown 探索未知。"},{"q":"10","answer":"D","options":["song","price","holiday","station"],"explanation":"a research station 一座科研站。"}]'::jsonb, 2, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U3', 'The Lost City of Atlantis', 'Thousands of years ago, the Greek writer Plato told of a great island (1)____ called Atlantis. According to his story, it was a rich and powerful (2)____ that suddenly sank beneath the waves in a single day and night. Ever since, people have (3)____ whether such a place ever truly existed. Some treasure hunters have spent their whole lives (4)____ for its ruins under the sea, but no one has found solid (5)____. A few researchers (6)____ that the tale was based on a real island near Greece, which was partly destroyed by a volcano long ago. Others (7)____ that Plato simply made the whole thing up to teach a lesson. The (8)____ that a wonderful city lies hidden somewhere on the ocean floor is hard to give up. Perhaps the (9)____ of Atlantis will never be solved. Still, the search goes on, (10)____ all the doubts of careful scientists.', 150, 2, '[{"q":"1","answer":"A","options":["kingdom","holiday","machine","ticket"],"explanation":"an island kingdom 一个岛国。"},{"q":"2","answer":"B","options":["garden","nation","dinner","song"],"explanation":"a rich and powerful nation 富强的国度。"},{"q":"3","answer":"C","options":["sold","painted","wondered","cooked"],"explanation":"wondered whether 想知道是否……。"},{"q":"4","answer":"D","options":["sleeping","singing","cooking","searching"],"explanation":"searching for its ruins 寻找它的遗迹。"},{"q":"5","answer":"A","options":["evidence","weather","music","grass"],"explanation":"solid evidence 确凿证据。"},{"q":"6","answer":"B","options":["sell","believe","sleep","cook"],"explanation":"researchers believe that 研究者认为。"},{"q":"7","answer":"C","options":["paint","sail","argue","swim"],"explanation":"others argue that 另一些人则主张。"},{"q":"8","answer":"D","options":["price","noise","ticket","idea"],"explanation":"the idea that 一座城藏在海底这一想法。"},{"q":"9","answer":"A","options":["mystery","garden","market","dinner"],"explanation":"the mystery of Atlantis 亚特兰蒂斯之谜。"},{"q":"10","answer":"B","options":["during","despite","towards","beside"],"explanation":"despite all the doubts 尽管有种种怀疑。"}]'::jsonb, 3, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U3', 'Crossing the Great Sahara', 'The Sahara is the largest hot (1)____ in the world, stretching across the north of Africa. For thousands of years, brave traders (2)____ its endless sand to carry salt and gold from one side to the other. Travelling there was always (3)____, for the days were burning hot and the nights were bitterly cold. Without enough water, a person could not (4)____ for long. Guides had to (5)____ the safest path by reading the stars and the shape of the dunes. Even today, with modern cars, crossing the desert is far from (6)____. Sandstorms can (7)____ a serious danger, hiding the road and turning day into night. Yet the Sahara still (8)____ many explorers, who long to test themselves against its harsh beauty. Each year a few (9)____ travellers set out to cross it on foot or by camel. For them, the empty desert is not a place to fear but a (10)____ to be met.', 156, 2, '[{"q":"1","answer":"C","options":["garden","market","desert","river"],"explanation":"the largest hot desert 最大的热带沙漠。"},{"q":"2","answer":"D","options":["sold","painted","sang","crossed"],"explanation":"crossed its endless sand 穿越无尽的沙海。"},{"q":"3","answer":"A","options":["difficult","easy","cheap","quiet"],"explanation":"was always difficult,与后文酷热严寒相符。"},{"q":"4","answer":"B","options":["sell","survive","sing","cook"],"explanation":"could not survive for long 无法长久存活。"},{"q":"5","answer":"C","options":["sell","drop","choose","lose"],"explanation":"choose the safest path 选出最安全的路。"},{"q":"6","answer":"D","options":["green","cheap","modern","easy"],"explanation":"far from easy 远非易事。"},{"q":"7","answer":"A","options":["pose","sell","paint","cook"],"explanation":"pose a serious danger 构成严重危险。"},{"q":"8","answer":"B","options":["sells","attracts","loses","breaks"],"explanation":"still attracts many explorers 仍吸引许多探险者。"},{"q":"9","answer":"C","options":["sleepy","lazy","brave","silent"],"explanation":"a few brave travellers 几位勇敢的旅人。"},{"q":"10","answer":"D","options":["dinner","price","song","challenge"],"explanation":"a challenge to be met 一项有待迎接的挑战。"}]'::jsonb, 4, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U3', 'Born to Explore', 'Human beings seem to be born (1)____. From the earliest times, our ancestors were never (2)____ to stay in one place. They climbed the highest mountains, crossed wide oceans, and walked into empty deserts simply to see what lay (3)____. This deep (4)____ to discover new things has shaped the whole history of our species. Every time one question is answered, a new one (5)____. When we finally reached the moon, we at once began to dream of the (6)____ beyond it. Some people ask why we should (7)____ so much time and money on exploration. The answer is that curiosity makes us (8)____ as human beings. Exploring teaches us about the world and, just as importantly, about (9)____. As long as there are unknown places to reach, there will always be people (10)____ enough to go and find them.', 140, 2, '[{"q":"1","answer":"A","options":["explorers","singers","farmers","sellers"],"explanation":"born explorers 天生的探索者。"},{"q":"2","answer":"B","options":["sleepy","content","angry","polite"],"explanation":"never content to stay 从不满足于待着不动。"},{"q":"3","answer":"C","options":["downstairs","yesterday","beyond","asleep"],"explanation":"see what lay beyond 看看更远处有什么。"},{"q":"4","answer":"D","options":["price","noise","garden","desire"],"explanation":"this deep desire 这种强烈的渴望。"},{"q":"5","answer":"A","options":["appears","sells","sleeps","eats"],"explanation":"a new one appears 又冒出一个新问题。"},{"q":"6","answer":"B","options":["prices","stars","songs","markets"],"explanation":"dream of the stars beyond it 梦想月球之外的群星。"},{"q":"7","answer":"C","options":["sell","lose","spend","break"],"explanation":"spend so much time and money 花费大量时间金钱。"},{"q":"8","answer":"D","options":["sell","sleep","fall","grow"],"explanation":"makes us grow 让我们成长。"},{"q":"9","answer":"A","options":["ourselves","themselves","himself","herself"],"explanation":"about ourselves 也认识我们自己(we → ourselves)。"},{"q":"10","answer":"B","options":["lazy","curious","sleepy","silent"],"explanation":"curious enough to go 好奇到愿意前往。"}]'::jsonb, 5, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U3', 'New Tools for the Deep Sea', 'Exploring the deep ocean is one of the hardest (1)____ that scientists face today. The water there is freezing cold and completely (2)____, and the pressure is strong enough to crush a submarine like a tin can. To reach such depths, engineers have built special machines that can (3)____ the huge pressure far below the surface. These vehicles carry bright lights and cameras, so that researchers can (4)____ creatures that have never been seen before. Some are sent down without any people inside and are (5)____ from a ship on the surface. Thanks to this modern (6)____, we now know that life exists even at the very (7)____ of the sea. Each dive brings back new (8)____ about a world that is stranger than any story. Yet most of the ocean floor is still a complete (9)____ to us. There is no (10)____ that the deep sea will keep surprising explorers for many years to come.', 156, 2, '[{"q":"1","answer":"C","options":["songs","prices","tasks","gardens"],"explanation":"one of the hardest tasks 最艰难的任务之一。"},{"q":"2","answer":"D","options":["sweet","loud","dry","dark"],"explanation":"completely dark 一片漆黑。"},{"q":"3","answer":"A","options":["resist","sell","sing","cook"],"explanation":"resist the huge pressure 顶住巨大的压力。"},{"q":"4","answer":"B","options":["sell","study","lose","drop"],"explanation":"study creatures 研究海洋生物。"},{"q":"5","answer":"C","options":["painted","cooked","controlled","sold"],"explanation":"controlled from a ship 由船上操控。"},{"q":"6","answer":"D","options":["weather","music","dinner","technology"],"explanation":"this modern technology 这种现代技术。"},{"q":"7","answer":"A","options":["bottom","price","song","ticket"],"explanation":"at the very bottom of the sea 在海的最底层。"},{"q":"8","answer":"B","options":["prices","facts","songs","tickets"],"explanation":"brings back new facts 带回新的事实。"},{"q":"9","answer":"C","options":["garden","market","mystery","dinner"],"explanation":"a complete mystery 一个完全的谜。"},{"q":"10","answer":"D","options":["price","garden","song","doubt"],"explanation":"there is no doubt that 毫无疑问。"}]'::jsonb, 6, 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U3 听力·对话 Choosing a Mystery', '上外版选择性必修第三册 U3 · dialogue', 3, 'Lin: Mr Brown asked us to choose a famous mystery for our class project. Any ideas?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U3 听力·短文 Born to Explore', '上外版选择性必修第三册 U3 · passage', 2, 'People have always wanted to explore the world around them.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U3 听力·对话 At the Science Museum', '上外版选择性必修第三册 U3 · dialogue', 3, 'Guide: Welcome. This model shows China''s Chang''e-4 probe.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U3 听力·短文 Facts about the Deep Ocean', '上外版选择性必修第三册 U3 · passage', 2, 'The deep ocean is one of the least explored places on Earth.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U3 听力·对话 A Nessie Documentary', '上外版选择性必修第三册 U3 · dialogue', 3, 'Sam: I watched a documentary about the Loch Ness Monster last night.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U3 听力·短文 A Tip for Taking Notes', '上外版选择性必修第三册 U3 · passage', 2, 'Here is a useful tip for when you listen to a report about a discovery.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (12, 'Write a Survey Report on Theories of a Mystery(就一个谜团的不同理论写调查报告)', 'How People View the Theories of a Mystery', '假设你们班开展了一次''读后分享''活动,就''巨石阵为何而建''调查了同学最认可哪种理论。请用英语写一篇约110-130词的调查报告,内容包括:① 介绍调查并转述调查问题;② 用比例/分数描述主要发现;③ 总结整体结论。注意恰当使用同位语从句(the theory that… / the belief that…)。', 'Your class held a read-and-share activity and surveyed which theory about why Stonehenge was built classmates find most believable. Write a survey report (about 110-130 words) that: 1) introduces the survey and restates the question; 2) describes the main findings using fractions or percentages; 3) ends with an overall conclusion. Try to use appositive clauses (the theory that… / the belief that…).', '["介绍调查并转述问题(We carried out a survey to find out…)","用比例描述主要发现(Nearly two thirds… / About one fourth…)","恰当使用同位语从句(the theory that… / the belief that…)","总结整体结论(Overall, it is clear that…)"]'::jsonb, 70, 100, 'Our class carried out a survey to find out which theory about why Stonehenge was built our classmates find most believable. Forty students took part and chose from three explanations. Nearly two thirds supported the theory that the monument worked as a calendar, since certain stones point to the sun at the solstices. About one fourth accepted the idea that it was once a burial ground, because human bones were found nearby. Only a few held the surprising belief that visitors from space lent a hand. Overall, it is clear that most of our classmates trust the scientific explanation rather than stranger stories. Even so, several of them said they still enjoy the mystery and hope that future discoveries will finally settle the question.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["We carried out a survey to find out which theory our classmates find most believable.","Nearly two thirds supported the theory that the monument worked as a calendar.","Only a few held the surprising belief that visitors from space lent a hand.","Overall, it is clear that most of our classmates trust the scientific explanation."]'::jsonb, '[{"wrong":"the theory which the monument was a calendar","correct":"the theory that the monument was a calendar","note":"从句完整、补充说明 theory 的内容,是同位语从句,用 that 不用 which。"},{"wrong":"Two thirds of students supports the theory.","correct":"Two thirds of the students support the theory.","note":"of the students 为复数,谓语用 support。"},{"wrong":"There is no doubt whether the result is clear.","correct":"There is no doubt that the result is clear.","note":"no doubt 后表''确信''用 that;whether 表''是否'',语义相反。"}]'::jsonb, '【谜团理论调查报告结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (12, 'elective3', 'U3', '{"title":"同位语从句(the belief / fact that …)速查","intro":"同位语从句跟在抽象名词后,用一个完整的句子说明该名词的''具体内容''。判断口诀:从句完整(不缺主/宾/状)→ 同位语,用 that/whether/wh-;从句缺成分 → 是定语从句,用 which/who/where/when。","table":{"headers":["引导词","用法 / 例句"],"rows":[["that","抽象名词 + 完整句:the fact that the world is round(that 只连接、不作成分)"],["whether","question/doubt 后表''是否'':the question whether life exists(不用 if、不用 that)"],["what/who","从句缺名词性成分:the question what these symbols mean(缺宾语)"],["how/why/when","从句只缺方式/原因/时间状语:the question how they moved the stones"]]},"specialRules":[{"rule":"同位语 that 从句完整、that 不可省略也不作成分;定语从句 that 在从句里作主语或宾语","mark":"the belief that the world is round(同位语) vs the belief that he expressed(定语,that 作宾语)"},{"rule":"常接同位语从句的抽象名词:belief, fact, idea, news, evidence, theory, hope, truth, doubt, question, problem","mark":"记住这串''内容名词''"},{"rule":"question/doubt(肯定句)后表''是否''用 whether,不用 that;但 no doubt 后用 that","mark":"the question whether… / There is no doubt that…"},{"rule":"先行词后若缺地点/时间状语,是定语从句,用 where/when,不是同位语","mark":"the place where they raised the stones(定语)"}],"why":["同位语从句是把名词的''内容''用一整句话说清楚,所以那句话本身是完整的,引导词(尤其是 that)只起连接作用;一旦句子里缺了主语、宾语或状语,就说明引导词要去''补那个缺口'',那就成了定语从句。"],"gaokaoPoints":["that 引导同位语从句 vs 定语从句的辨析(看从句完不完整);语法填空/改错高频。","question/doubt 后 whether 与 that 的选择;no doubt that 固定搭配。","同位语从句与先行词之间可被插入语隔开:The news came yesterday that…(从句后置)。"],"examVsReal":[{"exam":"the fact that he succeeded(书面/考试)","real":"the fact he succeeded","note":"考试要求写 that;口语里同位语 that 常被省略"},{"exam":"the question whether it is true(考试)","real":"the question of whether it''s true / whether it''s true","note":"考试用 whether;口语常加 of 或直接说 whether,极少用 if 引导名词后的同位语"}]}'::jsonb, 'sufe');
